css:
.briefsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1f2a37;
    background: linear-gradient(160deg, #f4f1ea 0%, #eae4d6 100%);
    border-radius: 18px;
}

.briefsim-container * {
    box-sizing: border-box;
}

.briefsim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #14233a 0%, #1f3a5f 55%, #2c5a7a 100%);
    color: #f6f1e7;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(20, 35, 58, 0.30);
}

.briefsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.briefsim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #e6c181;
    background: rgba(230, 193, 129, 0.14);
    padding: 5px 14px;
    border-radius: 999px;
}

.briefsim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e7ddca;
}

.briefsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2c4565;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.briefsim-period-counter #currentDay,
.briefsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #14233a;
}

.briefsim-round-name {
    background: #dbe6f0;
    color: #14233a;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.briefsim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a4b12;
    background: #f6e6cc;
    padding: 4px 12px;
    border-radius: 999px;
}

.briefsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.briefsim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e3dccb;
    box-shadow: 0 4px 14px rgba(20, 35, 58, 0.06);
    border-top: 4px solid #2c5a7a;
}

.briefsim-card-fit { border-top-color: #2c5a7a; }
.briefsim-card-margin { border-top-color: #1f7a55; }
.briefsim-card-relevance { border-top-color: #b07d2c; }
.briefsim-card-design { border-top-color: #6a4fb0; }

.briefsim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6b7785;
}

.briefsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #14233a;
}

.briefsim-card-fit .briefsim-value { color: #2c5a7a; }
.briefsim-card-margin .briefsim-value { color: #1f7a55; }
.briefsim-card-relevance .briefsim-value { color: #b07d2c; }
.briefsim-card-design .briefsim-value { color: #6a4fb0; font-size: 1.7rem; }

.briefsim-sublabel {
    font-size: 0.76rem;
    color: #8a93a0;
    line-height: 1.35;
}

.briefsim-margin-fail .briefsim-value { color: #c0392b; }
.briefsim-margin-floor .briefsim-value { color: #1f7a55; }

.briefsim-design-over { border-top-color: #c0392b; }
.briefsim-design-over .briefsim-value { color: #c0392b; }

.briefsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #14233a;
    color: #eef2f7;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.briefsim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.briefsim-budget-over #budgetDisplay { color: #f3a98e; }
.briefsim-budget-ok #budgetDisplay { color: #8fe0bb; }

.briefsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #b07d2c;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(20, 35, 58, 0.05);
}

.briefsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.briefsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #14233a;
    margin-bottom: 6px;
}

.briefsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #34404f;
}

.briefsim-briefing-text strong { color: #1f7a55; }
.briefsim-briefing-text em { color: #8a4b12; font-style: italic; }

.briefsim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e3dccb;
    box-shadow: 0 4px 14px rgba(20, 35, 58, 0.06);
}

.briefsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #14233a;
    border-bottom: 2px solid #efe9db;
    padding-bottom: 8px;
}

.briefsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #233347;
    margin: 14px 0 6px;
}

.briefsim-container select,
.briefsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cdbfa2;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fbf8f1;
    color: #1f2a37;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.briefsim-container select:focus,
.briefsim-container input[type="number"]:focus {
    outline: none;
    border-color: #b07d2c;
    box-shadow: 0 0 0 3px rgba(176, 125, 44, 0.18);
}

.briefsim-container select option {
    background-color: #ffffff;
    color: #1f2a37;
}

.briefsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #b07d2c;
}

.briefsim-range-readout,
.briefsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #2c4565;
    margin-top: 4px;
}

.briefsim-range-readout span:nth-child(2),
.briefsim-alloc-readout span:nth-child(2) {
    color: #1f7a55;
    font-weight: 800;
}

.briefsim-hint {
    font-size: 0.8rem;
    color: #8a93a0;
    margin-top: 4px;
    line-height: 1.4;
}

.briefsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.briefsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f7f3ea;
    border: 1px solid #e6ddcb;
    border-radius: 9px;
    padding: 8px 12px;
}

.briefsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #233347;
}

.briefsim-alloc-row input[type="number"] {
    width: 90px;
    flex: 0 0 90px;
}

.briefsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.briefsim-container .btn-primary {
    background: linear-gradient(135deg, #1f7a55 0%, #2c5a7a 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    color: #ffffff;
    box-shadow: 0 6px 16px rgba(31, 122, 85, 0.28);
}

.briefsim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.briefsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #cdbfa2;
    color: #6b7785;
}

.briefsim-coach {
    background: #14233a;
    color: #eef2f7;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(20, 35, 58, 0.22);
}

.briefsim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e6c181;
    margin-bottom: 8px;
}

.briefsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.briefsim-coach-body strong { color: #f0cf94; }
.briefsim-coach-body em { color: #f3b58e; font-style: italic; }

.briefsim-history,
.briefsim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e3dccb;
    box-shadow: 0 4px 14px rgba(20, 35, 58, 0.06);
}

.briefsim-history h3,
.briefsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #14233a;
}

.briefsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #233347;
}

.briefsim-container table#usfHistoryTable th {
    background: #f1ece0;
    color: #14233a;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e1d7c2;
}

.briefsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0ebdf;
}

.briefsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf7f0;
}

.briefsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .briefsim-container {
        padding: 14px;
    }
    .briefsim-header h1 {
        font-size: 1.7rem;
    }
    .briefsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .briefsim-value {
        font-size: 2rem;
    }
    .briefsim-card-design .briefsim-value {
        font-size: 1.4rem;
    }
    .briefsim-clock {
        margin-left: 0;
    }
    .briefsim-period-counter {
        font-size: 0.88rem;
    }
    .briefsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .briefsim-alloc-row {
        flex-wrap: wrap;
    }
    .briefsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .briefsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* v1.1.0 completion-message card (appended; self-contained) */
.briefsim-cm { background:#f5f7f9; color:#182028; border-radius:14px; padding:22px 24px; max-width:640px; margin:0 auto; font-family:inherit; box-shadow:0 8px 30px rgba(24,32,40,0.18); }
.briefsim-cm-head { text-align:center; border-bottom:1px solid #d5dde4; padding-bottom:14px; margin-bottom:16px; }
.briefsim-cm-title { font-size:13px; letter-spacing:.08em; text-transform:uppercase; color:#516170; font-weight:700; }
.briefsim-cm-scorewrap { margin:8px 0 2px; }
.briefsim-cm-score { font-size:52px; font-weight:800; color:#b8482e; line-height:1; }
.briefsim-cm-score-max { font-size:20px; color:#8695a2; font-weight:600; }
.briefsim-cm-grade { font-size:19px; font-weight:700; color:#182028; margin-top:4px; }
.briefsim-cm-badges { margin-top:12px; display:flex; flex-wrap:wrap; gap:8px; justify-content:center; }
.briefsim-cm-badge { font-size:12px; font-weight:700; padding:4px 11px; border-radius:999px; }
.briefsim-cm-met { background:#f6e0c8; color:#8a4a10; }
.briefsim-cm-fail { background:#f1dad4; color:#9c3a2b; }
.briefsim-cm-metrics { display:flex; flex-wrap:wrap; gap:12px; justify-content:center; margin-bottom:16px; }
.briefsim-cm-metric { background:#e7edf2; border-radius:10px; padding:12px 16px; min-width:100px; text-align:center; }
.briefsim-cm-metric-val { font-size:22px; font-weight:800; color:#243240; }
.briefsim-cm-metric-lbl { font-size:11px; letter-spacing:.05em; text-transform:uppercase; color:#516170; margin-top:3px; }
.briefsim-cm-insights { background:#e7edf2; border-radius:10px; padding:14px 18px; }
.briefsim-cm-insights-title { font-size:12px; letter-spacing:.06em; text-transform:uppercase; color:#516170; font-weight:700; margin-bottom:8px; }
.briefsim-cm-insights ul { margin:0; padding-left:18px; }
.briefsim-cm-insights li { font-size:14px; line-height:1.5; color:#243240; margin-bottom:7px; }

