(function() {
    'use strict';

    class BriefAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `The Custom Brief`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (EUR, in thousands where noted).
            this.CONTRACT = 480;          // EUR 480k contract cap
            this.MARGIN_FLOOR = 20;       // 20% contribution-margin floor
            this.COST_CEILING = 384;      // 480 * (1 - 0.20)
            this.FIRST_COSTING = 430;     // EUR 430k first rough costing
            this.GAP = 46;                // EUR 46k overrun to close
            this.DESIGN_BUDGET = 90;      // EUR 90k fixed design sub-budget
            this.OPEN_CAP = 40;           // open-module substitution ceiling, % of contact hours
            this.GUARANTEE = 90;          // 90 of 120 seats guaranteed

            // Concept truths (the on-margin, client-centric, conservative play).
            this.TRUE_OBJECTIVE = `cooanchor`;
            this.TRUE_RELEVANCE = `designinput`;
            this.TRUE_BESPOKE = `targeted`;
            this.TRUE_FILL = `ninety`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    fit: 25,
                    relevance: 25,
                    cost: this.FIRST_COSTING,
                    marginPct: Math.round((this.CONTRACT - this.FIRST_COSTING) / this.CONTRACT * 1000) / 10,
                    designUsed: 0,
                    designOver: false,
                    marginBreach: true,
                    bidLost: false,
                    fitHistory: [25],
                    marginHistory: [Math.round((this.CONTRACT - this.FIRST_COSTING) / this.CONTRACT * 100)],
                    relevanceHistory: [25],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a MIDDLING / neutral mix — never the textbook-correct play.
                state.decisions = {
                    objective: `managerlight`,
                    relevance: `validation`,
                    gap: 50,
                    strategy: 18, change: 18, execution: 18, coaching: 18, capstone: 18,
                    bespoke: `catalogue`,
                    mix: 20,
                    lever: `holdtrim`,
                    combine: `none`,
                    fill: `hundredfive`,
                    defend: `discount`,
                    impact: `satisfaction`,
                    conviction: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const obj = document.getElementById(`objectiveInput`);
                const rel = document.getElementById(`relevanceInput`);
                const gap = document.getElementById(`gapInput`);
                if (obj) decisions.objective = obj.value;
                if (rel) decisions.relevance = rel.value;
                if (gap) decisions.gap = parseInt(gap.value, 10);
                if (!Number.isFinite(decisions.gap) || decisions.gap < 0 || decisions.gap > 100) {
                    warn(`warn_gap_range`); return false;
                }
            } else if (round === 2) {
                const ids = [`strategy`, `change`, `execution`, `coaching`, `capstone`];
                ids.forEach((id) => {
                    const el = document.getElementById(id + `Input`);
                    if (el) decisions[id] = parseFloat(el.value);
                });
                const bes = document.getElementById(`bespokeInput`);
                if (bes) decisions.bespoke = bes.value;
                const parts = ids.map((id) => decisions[id]);
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round(parts.reduce((a, b) => a + b, 0));
                if (total !== this.DESIGN_BUDGET) {
                    warn(`warn_alloc_total`); return false;
                }
            } else if (round === 3) {
                const mix = document.getElementById(`mixInput`);
                const lev = document.getElementById(`leverInput`);
                const comb = document.getElementById(`combineInput`);
                if (mix) decisions.mix = parseInt(mix.value, 10);
                if (lev) decisions.lever = lev.value;
                if (comb) decisions.combine = comb.value;
                if (!Number.isFinite(decisions.mix) || decisions.mix < 0 || decisions.mix > 60) {
                    warn(`warn_mix_range`); return false;
                }
            } else if (round === 4) {
                const fill = document.getElementById(`fillInput`);
                const def = document.getElementById(`defendInput`);
                const imp = document.getElementById(`impactInput`);
                const cv = document.getElementById(`convictionInput`);
                if (fill) decisions.fill = fill.value;
                if (def) decisions.defend = def.value;
                if (imp) decisions.impact = imp.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let fitDelta = 0, relevanceDelta = 0, costDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Decode the brief — triangulate the COO (budget), HR (sponsor), managers (learners).
                switch (d.objective) {
                    case `cooanchor`: fitDelta += 18; relevanceDelta += 6; coachKey = `coach_r1_coo`; break;
                    case `hrtransform`: fitDelta += 4; relevanceDelta -= 6; coachKey = `coach_r1_hr`; break;       // Common Error 1
                    case `managerlight`: fitDelta -= 4; relevanceDelta += 10; coachKey = `coach_r1_managerlight`; break;
                    case `allthree`: fitDelta -= 8; relevanceDelta -= 4; coachKey = `coach_r1_allthree`; break;     // can't maximise all
                }

                // The manager survey is relevance data — a design input, not a slide (Common Error 5).
                switch (d.relevance) {
                    case `designinput`: relevanceDelta += 16; fitDelta += 4; if (d.objective === `cooanchor`) coachKey = `coach_r1_sharp`; break;
                    case `validation`: relevanceDelta += 6; break;
                    case `slide`: relevanceDelta -= 10; fitDelta -= 2; coachKey = `coach_r1_slide`; break;
                }

                // Confronting the binding margin gap honestly sets up Round 3.
                if (d.gap >= 60) { fitDelta += 4; }
                else if (d.gap <= 25) { fitDelta -= 6; coachKey = `coach_r1_lowgap`; }

                summaryKey = (d.objective === this.TRUE_OBJECTIVE && d.relevance === this.TRUE_RELEVANCE) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Allocate the EUR 90k design budget as a portfolio + choose bespoke vs open.
                // Concentration on the fit-earning modules (execution, capstone, coaching) rewards;
                // starving coaching or spreading evenly across low-leverage modules underperforms.
                const earners = (d.execution || 0) + (d.capstone || 0) + (d.coaching || 0);
                const earnerShare = earners / this.DESIGN_BUDGET; // portfolio quality 0..1
                if (earnerShare >= 0.62) { fitDelta += 8; relevanceDelta += 4; }
                else if (earnerShare >= 0.48) { fitDelta += 3; }
                else { fitDelta -= 4; coachKey = `coach_r2_spread`; }
                if ((d.coaching || 0) < 8) { relevanceDelta -= 6; fitDelta -= 4; coachKey = `coach_r2_nocoaching`; }

                // Bespoke strategy — targeted custom where fit pays; bespoke-everything blows the
                // envelope (Common Error 2); open-everywhere is cheap but generic.
                switch (d.bespoke) {
                    case `targeted`:
                        fitDelta += 14; relevanceDelta += 6; ds.designUsed = this.DESIGN_BUDGET;
                        coachKey = (earnerShare >= 0.62) ? `coach_r2_targeted` : coachKey;
                        break;
                    case `everything`:
                        // EUR 132k spent against a EUR 90k envelope -> EUR 42k bleeds into delivery cost.
                        fitDelta += 8; ds.designUsed = 132; ds.designOver = true; costDelta += 42;
                        coachKey = `coach_r2_everything`;
                        break;
                    case `catalogue`:
                        fitDelta -= 10; relevanceDelta -= 4; ds.designUsed = 55;
                        coachKey = `coach_r2_catalogue`;
                        break;
                }

                summaryKey = (d.bespoke === `targeted` && earnerShare >= 0.62 && (d.coaching || 0) >= 8) ? `sum_r2_good` : (d.bespoke === `everything` ? `sum_r2_over` : `sum_r2_weak`);
            } else if (round === 3) {
                // Open/custom mix + the margin solve. This round drives margin via cost.
                // Open share lowers fit (generic) but is allowed up to 40%; above the cap it stops
                // being a custom programme at all.
                const open = d.mix;
                if (open > this.OPEN_CAP) {
                    fitDelta -= 18; relevanceDelta -= 6; costDelta -= 8; coachKey = `coach_r3_overcap`;
                } else if (open >= 25 && open <= 40) {
                    fitDelta -= 4; costDelta -= 6; coachKey = `coach_r3_balancedmix`;
                } else if (open >= 10) {
                    fitDelta -= 1; costDelta -= 3;
                } else {
                    // Almost no open substitution: high fit but no help on cost.
                    fitDelta += 3; coachKey = `coach_r3_allcustom`;
                }

                // Margin levers: each closes part of the EUR 46k gap with different collateral.
                const applyLever = (lever, primary) => {
                    switch (lever) {
                        case `swapopen`: costDelta -= 28; fitDelta -= 6; break;
                        case `facultyself`: costDelta -= 18; fitDelta -= 1; break;
                        case `cutcoaching`: costDelta -= 30; relevanceDelta -= 12; fitDelta -= 8; if (primary) coachKey = `coach_r3_cutcoaching`; break; // Common Error 3
                        case `holdtrim`: costDelta -= 46; relevanceDelta -= 10; fitDelta -= 6; if (primary) coachKey = `coach_r3_holdtrim`; break;
                        case `none`: break;
                    }
                };
                applyLever(d.lever, true);
                if (d.combine && d.combine !== `none` && d.combine !== d.lever) {
                    applyLever(d.combine, false);
                }

                // Best safe solve: swapopen + facultyself protects the deliverable AND clears the gap.
                if ((d.lever === `swapopen` && d.combine === `facultyself`) || (d.lever === `facultyself` && d.combine === `swapopen`)) {
                    fitDelta += 6; coachKey = `coach_r3_safesolve`;
                }

                summaryKey = `sum_r3_weak`;
                if (d.lever === `cutcoaching` || d.combine === `cutcoaching`) summaryKey = `sum_r3_mutilate`;
                else if (open <= this.OPEN_CAP && ((d.lever === `swapopen` && d.combine === `facultyself`) || (d.lever === `facultyself` && d.combine === `swapopen`))) summaryKey = `sum_r3_good`;
            } else if (round === 4) {
                // Pitch: price the guarantee, defend the mix, commit to measurable impact.
                switch (d.fill) {
                    case `ninety`: fitDelta += 8; costDelta -= 2; coachKey = `coach_r4_ninety`; break;
                    case `hundredfive`: fitDelta += 2; costDelta += 4; coachKey = `coach_r4_hundredfive`; break;
                    case `onetwenty`: fitDelta -= 10; costDelta += 14; coachKey = `coach_r4_onetwenty`; break;  // Common Error 4
                }

                switch (d.defend) {
                    case `evidence`: fitDelta += 10; relevanceDelta += 2; coachKey = (d.fill === `ninety`) ? `coach_r4_evidence` : coachKey; break;
                    case `discount`: costDelta += 24; fitDelta -= 2; coachKey = `coach_r4_discount`; break;       // caves on margin
                    case `morecustom`: costDelta += 30; fitDelta += 2; coachKey = `coach_r4_morecustom`; break;   // breaks the envelope
                }

                switch (d.impact) {
                    case `metrics`: fitDelta += 12; relevanceDelta += 4; break;
                    case `satisfaction`: fitDelta -= 2; break;
                    case `rhetoric`: fitDelta -= 10; coachKey = `coach_r4_rhetoric`; break;                       // COO rejects rhetoric
                }

                // Holding the floor under pressure protects margin (resists the discount instinct).
                if (d.conviction >= 60) { costDelta -= Math.round((d.conviction - 60) / 8); }
                else { costDelta += Math.round((60 - d.conviction) / 8); fitDelta -= 2; }

                summaryKey = (d.fill === `ninety` && d.defend === `evidence` && d.impact === `metrics`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Cost / margin accounting.
            ds.cost = Math.max(300, Math.round(ds.cost + costDelta));
            ds.marginPct = Math.round((this.CONTRACT - ds.cost) / this.CONTRACT * 1000) / 10;
            ds.marginBreach = ds.marginPct < this.MARGIN_FLOOR;

            // Fit and relevance move on their deltas (start low, plenty of headroom).
            ds.fit = Math.max(0, Math.min(100, ds.fit + fitDelta));
            ds.relevance = Math.max(0, Math.min(100, ds.relevance + relevanceDelta));

            ds.fitHistory.push(Math.round(ds.fit));
            ds.marginHistory.push(Math.round(ds.marginPct));
            ds.relevanceHistory.push(Math.round(ds.relevance));

            // v1.1.0: persist composite for instructor gradebook (results_utils.php Ruta 1).
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = this._composite(ds);

            // Final-round bid outcome: a binary win/loss against two competitors.
            if (round === this.ROUNDS.length) {
                const composite = ds.fit * 0.4 + ds.relevance * 0.3 + Math.min(100, Math.max(0, ds.marginPct * 3)) * 0.3;
                ds.bidLost = ds.marginBreach || composite < 55;
            }

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                fit: Math.round(ds.fit),
                fitDelta: Math.round(fitDelta),
                relevance: Math.round(ds.relevance),
                relevanceDelta: Math.round(relevanceDelta),
                cost: Math.round(ds.cost),
                marginPct: ds.marginPct,
                marginBreach: ds.marginBreach,
                designUsed: ds.designUsed,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

