        _composite(ds) {
            // v1.1.0 single source of truth - verbatim v1.0.0 formula (scoring unchanged).
            const fit = Math.round(ds.fit);
            const relevance = Math.round(ds.relevance);
            const marginPct = Math.round(ds.marginPct * 10) / 10;
            return Math.round(fit * 0.4 + relevance * 0.3 + Math.min(100, Math.max(0, marginPct * 3)) * 0.3);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const fit = Math.round(ds.fit);
            const relevance = Math.round(ds.relevance);
            const marginPct = Math.round(ds.marginPct * 10) / 10;

            const onMargin = marginPct >= this.MARGIN_FLOOR;
            const strongFit = fit >= 60 && relevance >= 55;
            const composite = this._composite(ds);
            const won = onMargin && composite >= 55 && !ds.bidLost;

            let performanceKey = `grade_lost`;
            if (won && strongFit && composite >= 74) performanceKey = `grade_framework`;
            else if (won && strongFit) performanceKey = `grade_onmargin`;
            else if (won) performanceKey = `grade_thin`;
            else if (!onMargin && composite >= 55) performanceKey = `grade_breach`;
            else if (composite >= 48) performanceKey = `grade_short`;
            const performance = window.mySimulation.t(performanceKey);
            const met = won && strongFit && composite >= 74;

            const insights = [];
            if (won && strongFit) insights.push(window.mySimulation.t(`insight_won`));
            else if (!onMargin) insights.push(window.mySimulation.t(`insight_breach`));
            else if (!won) insights.push(window.mySimulation.t(`insight_lost`));
            else insights.push(window.mySimulation.t(`insight_thin`));

            if (relevance < 45) insights.push(window.mySimulation.t(`insight_relevance`));
            if (fit < 45) insights.push(window.mySimulation.t(`insight_fit`));
            if (marginPct >= this.MARGIN_FLOOR + 2 && strongFit) insights.push(window.mySimulation.t(`insight_durable`));
            if (won && strongFit && composite >= 74) insights.push(window.mySimulation.t(`insight_repeat`));

            return {
                fit: fit,
                relevance: relevance,
                marginPct: marginPct,
                onMargin: onMargin,
                won: won,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                met: met,
                strongFit: strongFit,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            const s = summary || {};
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || (s.performanceKey ? t(s.performanceKey) : ``);
            const badges = [];
            badges.push(`<span class="briefsim-cm-badge ` + (s.met ? `briefsim-cm-met` : `briefsim-cm-fail`) + `">` + (s.met ? t(`cm_met`) : t(`cm_not_met`)) + `</span>`);
            if (s.onMargin === false) badges.push(`<span class="briefsim-cm-badge briefsim-cm-fail">` + t(`cm_fail_margin`) + `</span>`);
            if (s.won === false) badges.push(`<span class="briefsim-cm-badge briefsim-cm-fail">` + t(`cm_fail_lost`) + `</span>`);
            if (s.strongFit === false) badges.push(`<span class="briefsim-cm-badge briefsim-cm-fail">` + t(`cm_fail_fit`) + `</span>`);
            const kpi = (label, val) => `<div class="briefsim-cm-metric"><div class="briefsim-cm-metric-val">` + val + `</div><div class="briefsim-cm-metric-lbl">` + label + `</div></div>`;
            const kpis = kpi(t(`cm_fit`), (s.fit != null ? Math.round(s.fit) : 0))
                + kpi(t(`cm_relevance`), (s.relevance != null ? Math.round(s.relevance) : 0))
                + kpi(t(`cm_margin`), (s.marginPct != null ? s.marginPct : 0) + `%`)
                + kpi(t(`cm_index`), score + `/100`);
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `<div class="briefsim-cm">`
                + `<div class="briefsim-cm-head"><div class="briefsim-cm-title">` + t(`cm_title`) + `</div>`
                + `<div class="briefsim-cm-scorewrap"><span class="briefsim-cm-score">` + score + `</span><span class="briefsim-cm-score-max">/100</span></div>`
                + `<div class="briefsim-cm-grade">` + grade + `</div>`
                + `<div class="briefsim-cm-badges">` + badges.join(``) + `</div></div>`
                + `<div class="briefsim-cm-metrics">` + kpis + `</div>`
                + `<div class="briefsim-cm-insights"><div class="briefsim-cm-insights-title">` + t(`cm_insights_title`) + `</div><ul>` + insights + `</ul></div>`
                + `</div>`;
        }

